//! `timed` client (issue #369): the time-of-day service.
//!
//! The `os.lazy.timed.v1` stubs and its [`Client`] are generated by `midlc`
//! from `idl/timed.midl`; this module only names them for native programs.
//! A service failure comes back as [`CallError::Remote`] with the service's
//! own text, and every call is bounded by the crate-wide default deadline.

use super::client::Native;

/// The generated `os.lazy.timed.v1` stubs.
pub use messenger_generated::os_lazy_timed_v1 as wire;

/// Registered service name.
pub const NAME: &str = wire::SERVICE_NAME;

/// The interface id every `timed` parcel carries.
pub const INTERFACE: u64 = wire::INTERFACE_ID;

/// `Now()` answer.
pub use wire::NowReply as Now;

/// A blocking client of the `timed` service: `Client::connect(Native)`.
pub type Client = wire::Client<Native>;
